type OrderStatus = 'processing' | 'shipped' | 'delivered' | 'cancelled' | 'returned';
type Order =
  | { id: number; status: 'processing' }
  | { id: number; status: 'shipped'; trackingNumber: string }
  | { id: number; status: 'delivered'; trackingNumber: string; deliveredAt: string }
  | { id: number; status: 'cancelled'; cancelReason: string }
  | { id: number; status: 'returned'; trackingNumber: string; deliveredAt: string; refundCents: number };
type Line = { sku: string; quantity: number; unitPriceCents: number; giftWrapped: boolean };
declare function loadOrder(id: number): Promise<Order>;

type MyExclude<T, U> = T extends U ? never : T;
type MyExtract<T, U> = T extends U ? T : never;
type MyReturnType<F> = F extends (...args: any[]) => infer R ? R : never;
type UnwrapPromise<T> = T extends Promise<infer V> ? V : T;

// The Order variant(s) whose status is S.
type OrderWithStatus<S extends OrderStatus> = MyExtract<Order, { status: S }>;

// The keys of T whose values are assignable to V.
type KeysOfType<T, V> = { [K in keyof T]-?: T[K] extends V ? K : never }[keyof T];

// ---- Type tests (do not edit) ----
type T1 = Expect<Equal<MyExclude<OrderStatus, 'cancelled' | 'returned'>, 'processing' | 'shipped' | 'delivered'>>;
type T2 = Expect<Equal<MyExtract<OrderStatus, 'shipped' | 'refunded'>, 'shipped'>>;
type T3 = Expect<Equal<MyReturnType<typeof loadOrder>, Promise<Order>>>;
type T4 = Expect<Equal<MyReturnType<() => void>, void>>;
type T5 = Expect<Equal<UnwrapPromise<Promise<Order>>, Order>>;
type T6 = Expect<Equal<UnwrapPromise<number>, number>>;
type T7 = Expect<Equal<OrderWithStatus<'cancelled'>, { id: number; status: 'cancelled'; cancelReason: string }>>;
type T8 = Expect<Equal<OrderWithStatus<'delivered' | 'returned'>['deliveredAt'], string>>;
type T9 = Expect<Equal<KeysOfType<Line, number>, 'quantity' | 'unitPriceCents'>>;
type T10 = Expect<Equal<KeysOfType<Line, boolean>, 'giftWrapped'>>;

const shippedOnly: OrderWithStatus<'shipped'> = { id: 1042, status: 'shipped', trackingNumber: '1Z-999' };
console.log(shippedOnly.trackingNumber);
